sources.setdefault('Automatic PGN · needs attention',['ui/pgn-output.js'])
for i,code in enumerate(('en','es','fr','de','pt','it','nl','pl')):
    p=ROOT/'locales'/f'{code}.json';data=json.loads(p.read_text(encoding='utf-8'))
    for key in sources:
        match=next((value for prefix,value in sorted(rows.items(),key=lambda r:-len(r[0])) if key.startswith(prefix)),None)
        if match:data['messages'][key]=key if code=='en' else match.split('|')[i-1]
        elif key.startswith('C:\\Chess\\PGN\\'):data['messages'][key]=key
    p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'locales/sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
